oop-lab:
class Solution {
    private int stock;

    public Solution(int initialStock) {
        if (initialStock < 0) {
            throw new IllegalArgumentException("initialStock must be non-negative");
        }
        stock = initialStock;
    }

    public boolean reserve(int quantity) {
        if (quantity <= 0 || quantity > stock) {
            return false;
        }
        stock -= quantity;
        return true;
    }

    public int remaining() {
        return stock;
    }
}

polymorphism-lab:
class Solution {
    public interface DiscountPolicy {
        int discount(int subtotal);
    }

    public int payable(int subtotal, DiscountPolicy policy) {
        if (subtotal < 0) {
            throw new IllegalArgumentException("subtotal must be non-negative");
        }
        java.util.Objects.requireNonNull(policy, "policy");
        int discount = policy.discount(subtotal);
        if (discount < 0 || discount > subtotal) {
            throw new IllegalArgumentException("discount outside contract");
        }
        return subtotal - discount;
    }
}

