exceptions-lab:
class Solution {
    public int parsePort(String text) {
        if (text == null) {
            throw new IllegalArgumentException("port is required");
        }
        final int port;
        try {
            port = Integer.parseInt(text.trim());
        } catch (NumberFormatException cause) {
            throw new IllegalArgumentException("port must be an integer", cause);
        }
        if (port < 1 || port > 65535) {
            throw new IllegalArgumentException("port outside range");
        }
        return port;
    }
}

streams-lab:
class Solution {
    public int totalPositiveEven(java.util.List<Integer> values) {
        return values.stream()
                .filter(java.util.Objects::nonNull)
                .filter(value -> value > 0 && value % 2 == 0)
                .mapToInt(Integer::intValue)
                .sum();
    }
}

concurrency-lab:
class Solution {
    public int count(int workers, int iterations) {
        if (workers < 1 || workers > 8 || iterations < 0 || iterations > 10000) {
            throw new IllegalArgumentException("arguments outside exercise bounds");
        }
        java.util.concurrent.ExecutorService executor =
                java.util.concurrent.Executors.newFixedThreadPool(workers);
        java.util.concurrent.atomic.AtomicInteger counter =
                new java.util.concurrent.atomic.AtomicInteger();
        try {
            java.util.List<java.util.concurrent.Future<?>> futures =
                    new java.util.ArrayList<java.util.concurrent.Future<?>>();
            for (int worker = 0; worker < workers; worker++) {
                futures.add(executor.submit(() -> {
                    for (int index = 0; index < iterations; index++) {
                        counter.incrementAndGet();
                    }
                }));
            }
            for (java.util.concurrent.Future<?> future : futures) {
                future.get();
            }
            return counter.get();
        } catch (InterruptedException cause) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("count interrupted", cause);
        } catch (java.util.concurrent.ExecutionException cause) {
            throw new IllegalStateException("worker failed", cause);
        } finally {
            executor.shutdownNow();
        }
    }
}

modern-apis-lab:
class Solution {
    public java.util.List<String> normalizedLines(String text) {
        if (text == null) {
            throw new IllegalArgumentException("text is required");
        }
        return text.lines()
                .map(String::strip)
                .filter(line -> !line.isBlank())
                .collect(java.util.stream.Collectors.toList());
    }
}

records-sealed-lab:
class Solution {
    public sealed interface Result permits Accepted, Rejected {}
    public record Accepted(int remaining) implements Result {}
    public record Rejected(String reason) implements Result {}

    public Result reserve(int stock, int requested) {
        if (stock < 0) {
            return new Rejected("invalid-stock");
        }
        if (requested <= 0) {
            return new Rejected("invalid-quantity");
        }
        if (requested > stock) {
            return new Rejected("insufficient-stock");
        }
        return new Accepted(stock - requested);
    }
}

java21-lab:
class Solution {
    public record Order(String id, int quantity) {}

    public String describe(Object value) {
        return switch (value) {
            case Order(String id, int quantity) when quantity > 0 -> id + ":" + quantity;
            case Order order -> "empty";
            case null -> "missing";
            default -> "unsupported";
        };
    }
}

testing-design-lab:
class Solution {
    public boolean acceptsPolicy(java.util.function.IntUnaryOperator policy) {
        int[] inputs = {0, 29999, 30000, 30001};
        int[] expected = {3000, 3000, 0, 0};
        try {
            for (int index = 0; index < inputs.length; index++) {
                if (policy.applyAsInt(inputs[index]) != expected[index]) {
                    return false;
                }
            }
            try {
                policy.applyAsInt(-1);
                return false;
            } catch (IllegalArgumentException expectedFailure) {
                return true;
            }
        } catch (RuntimeException unexpectedFailure) {
            return false;
        }
    }
}
